<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\Accessor\TenantRootAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantRootAccessor trait.
 *
 * Covers null default, string/VO assignment via withRoot,
 * getRoot/root accessors, and isRootChanged with/without original.
 */
class TenantRootAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRoot creates a new instance with the Root set
     * from a string value, and getRoot returns the primitive string.
     */
    public function testWithRootFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantRootAccessorUnitTest();

        // Act
        $result = $holder->withRoot(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isRoot());
    }
    /**
     * Asserts that withroot has access to the value object
     * from a string value, and getRoot returns the primitive string.
     */
    public function testWithRootFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantRootAccessorUnitTest();

        // Act
        $result = $holder->withRoot(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->root()->value());
    }
    public function testChangedRoot(): void
    {
        // Arrange
        $holder = new ImplWithTenantRootAccessorUnitTest();
        $original = $holder->withRoot( true);
        $same = $holder->withRoot( true);
        $modified = $holder->withRoot(false);

        // Act
        $unchanged = $holder->isRootChanged();
        $withSame = $original->isRootChanged( $same );
        $withDiferent = $original->isRootChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantRootAccessorUnitTest
{
  use TenantRootAccessor;
}
